// TH16 v1.00a Stage 5 MainSub01 (st05.ecl.txt:1053-1092)
// 三轮双侧 ECir01 编队；ECir01 (156-191)、ECir01_at (264-330)、
// ECir01DeadAttack1/Et1 (193-262)。源坐标以画面上方中点为 (0,0)。

const TIME_LIMIT: int = 2280;
const OPENING_BUFFER: int = 120;

const FAN_SPREAD: int = 3641;  // 0.34906584 rad 逐路间隔
const BODY_R: fx = 8fx;        // setHitbox(16,16) -> 16*0.5
const HURT_R: fx = 12fx;       // setHurtbox(24,24) -> 24*0.5

const EXIT_Y: fx = 448fx;      // 场面下边界；敌在 y>704 才被屏外回收

// ---- ECir01_at (264-330)：10 波扇形，模式1固定方向扇形 ----
async sub ecir01_fan() {
    wait(10);                                   // 0267
    var n: int = 1;                             // etCount: 1(E)/1(N)/3(H)/3(LO)
    var jitter: int = 182;                      // RANDF2 幅度 0.017453292 rad (E)
    var period: int = 120;                      // wait([-1])  E/N/H/LO = 120/40/120/60
    var speed: fx = 1fx;                        // etSpeed s0 1.0(E)/3.0(N,H,LO)
    var rank: int = global(GVAR_RANK);
    if rank == 1 {
        jitter = 1820;                          // 0.17453292 rad
        period = 40;
        speed = 3fx;
    } else if rank == 2 {
        n = 3;
        jitter = 3641;                          // 0.34906584 rad
        speed = 3fx;
    } else if rank >= 3 {
        n = 3;
        jitter = 3641;
        period = 60;
        speed = 3fx;
    }
    // EX type 0x2 a=1 (ANIM)：出生时 position -= 4*velocity
    var back: fx = 0fx - 4fx * speed;
    for k in 0..10 {                            // $B = 10
        var aim: angle = aim_player();           // %ANGLE_PLAYER，每波读取一次
        var j: int = (rand(65536) - 32768) * jitter / 32768;  // %RANDF2 * 幅度
        var base: angle = aim + (j as angle);
        for i in 0..n {
            // 模式1：alpha+F(N,i)；N=3 时为 0,-delta,+delta
            var off: int = 0;
            if i == 1 { off = 0 - FAN_SPREAD; }
            if i == 2 { off = FAN_SPREAD; }
            var a: angle = base + (off as angle);
            _ = fire(TH16_BALL, 6,
                     $self_x + back * cos(a), $self_y + back * sin(a),
                     speed, a, none, none);
        }
        wait(period);
    }
}

// ---- ECir01DeadAttackEt1 (203-262)：固定方向环 alpha=90°，4 波 ----
// flagSet(288)=0x20 受击/体碰门 + 0x100；这里用永久无敌 + 关闭体碰表达。
async sub ecir01_dead_et1() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var n: int = 1;                             // etCount 1(E)/13(N,H,LO)
    var speed: fx = 1.2fx;                      // etSpeed s0 1.2(E)/1.6(N)/2.2(H,LO)
    var period: int = 7;                        // etOn 后 wait([-1]) 7(E)/10(N,H,LO)
    var rank: int = global(GVAR_RANK);
    if rank == 1 {
        n = 13;
        speed = 1.6fx;
        period = 10;
    } else if rank == 2 {
        n = 13;
        speed = 2.2fx;
        period = 10;
    } else if rank >= 3 {
        n = 13;
        speed = 2.2fx;
        period = 10;
    }
    // etDist 32 与 EX type 0x2 a=1 的出生退位移合成：沿弹角净距离 32-4*speed
    var dist: fx = 32fx - 4fx * speed;
    // 记录2 为 WAIT 90(E)/40(LO)，其后没有记录，不产生可观察行为，故不转写。
    for k in 0..4 {                             // $B = 4
        for i in 0..n {
            var a: angle = 90deg + ((i * 65536 / n) as angle);
            _ = fire(TH16_RICE, 6,
                     $self_x + dist * cos(a), $self_y + dist * sin(a),
                     speed, a, none, none);
        }
        wait(period);
    }
}

// ---- ECir01DeadAttack1 (193-201) ----
// diffF %F0 / diffI $I0 / $I1 只写入死亡敌自身槽，Et1 未读取；moveSetMirror(0)
// 在本卡无镜像时为空操作。保留创建子敌与参数。
sub ecir01_death() {
    _ = spawn_enemy($self_x, $self_y, 10, 0, 0, 0, ecir01_dead_et1);
}

// ---- ECir01 (156-191) ----
async sub ecir01(bx: fx, by: fx) {
    set_invuln(65535);                          // 训练外壳：真实敌无敌
    set_hurtbox(HURT_R);                        // 0162
    set_hitbox(BODY_R);                         // 0163
    // flagSet(15)=0x1|0x2|0x4|0x8：受击门/体碰门/横纵屏外回收开关。
    // 无敌由外壳承担，0x4/0x8 在出生 60 帧内不会触发回收；体碰按 0x2 在 t=60 清除。
    set_enemy_flag(ENEMY_NO_BODY, 1);           // 0166
    // movePosRel(RANDF2*16, RANDF2*16) 已在出生坐标中给出，随后 REL 于 60 帧
    // 以 mode1(二次加速) 回到 0；ABS 不动，故等价于 move_to(base)。
    move_to(60, bx, by, EASE_QUAD_IN);          // 0173-0174
    wait(60);                                   // 0175
    // setDeath("ECir01DeadAttack1")：源在击破时执行；外壳无敌且目标无死亡脚本接口，
    // 击破不可达，替代触发点见下方循环。
    set_enemy_flag(ENEMY_NO_BODY, 0);           // 0177 flagClear(15)
    spawn ecir01_fan();                         // 0180 @ECir01_at() async
    wait(60);                                   // 0181
    // getAngle(%F2, FINAL_X, FINAL_Y, 0.0, 360.0) -> 朝 (0,360)
    var a: angle = atan2(360fx - $self_y, 0fx - $self_x);
    move_vel(0, a, 0fx, EASE_LINEAR);           // 0183 moveVel(angle, 0)
    move_speed(120, 1fx, EASE_LINEAR);          // 0184 moveSpeedTime(120,0,1.0)
    // 0186-0189 为无限 wait 循环；源中本敌只在被击破时退场。
    // setDeath 由击破触发；外壳无敌且目标无死亡脚本接口，击破不可达。
    // 代替触发点取本敌离开场面下边界（y>=448）的时刻：此时仍在弹场内可发弹，
    // 而敌继续按源漂移，直到 y>704 被引擎屏外回收；不移除敌，避免截断后续发射。
    var fired: int = 0;
    loop {
        if fired == 0 && $self_y >= EXIT_Y {
            fired = 1;
            ecir01_death();
        }
        wait(1);
    }
}

// ---- MainSub01 (1053-1092)：三轮，每轮 8 对，间隔 30 帧 ----
// enmCreate 相对父 FINAL；MainFront 由 STAGE 主路径调用，父位置为 (0,0)。
sub spawn_ecir(bx: fx, by: fx) {
    var ox: fx = ((rand(65536) - 32768) as fx) / 32768 * 16fx;  // RANDF2*16
    var oy: fx = ((rand(65536) - 32768) as fx) / 32768 * 16fx;
    _ = spawn_enemy(bx + ox, by + oy, 150, 0, 0, 0, ecir01(bx, by));
}

async sub wave_pattern() {
    wait(OPENING_BUFFER);
    for round in 0..3 {
        var a: fx = 0fx;                        // %A = 0，每轮 8 次 +24
        for i in 0..8 {
            spawn_ecir(a, 48fx);
            spawn_ecir(0fx - a, 48fx);
            a = a + 24fx;
            wait(30);
        }
        if round == 0 { wait(250); }            // 1067
        if round == 1 { wait(150); }            // 1079
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(1); }
}

